import fs from 'node:fs';
import {env} from 'cloudflare:workers';
import {D1,setup,applicant,complete} from './production-identity-journey.mjs';
import {sandboxCompletionPolicy,resolveSandboxPolicy} from '../../app/lib/sandbox-completion-policy.ts';
import {agreementHash} from '../../app/lib/agreement-acceptance.ts';
import {createSandboxCapture,sandboxIdentityProvider} from '../../app/lib/sandbox-identity.ts';
export async function installSandbox(db,overrides){const raw=overrides?JSON.stringify(overrides):undefined,policy=resolveSandboxPolicy(raw);for(const name of fs.readdirSync('sandbox-migrations').filter(f=>f.endsWith('.sql')).sort())db.sql.exec(fs.readFileSync('sandbox-migrations/'+name,'utf8'));db.sql.prepare('INSERT INTO sandbox_completion_instance VALUES(1,?,?,?)').run('sandbox',sandboxCompletionPolicy.version,await agreementHash(JSON.stringify(policy)));db.sql.prepare('INSERT INTO sandbox_retention_policy VALUES(1,?,?)').run(await agreementHash(JSON.stringify(policy)),policy.retentionDays);const primary=new D1();const runtime={DB:primary,SANDBOX_DB:db,LOKD_APP_STAGE:'prelaunch',LOKD_SANDBOX_COMPLETION_ENABLED:'true',LOKD_SANDBOX_POLICY_JSON:raw??''};Object.assign(env,runtime);return runtime;}
export async function sandboxApplicant(){const x=await setup();const runtime=await installSandbox(x.db);return {...x,runtime,actor:applicant,close(){x.db.sql.close();runtime.DB.sql.close();}};}
export async function sandboxReady(options={}){let runtime;const x=await complete({...options,identityFactory:async(db,caseId)=>{runtime=await installSandbox(db,options.policyOverrides);const capture=await createSandboxCapture(runtime,applicant,{applicantId:caseId,applicantVersion:2,consentVersion:sandboxCompletionPolicy.consentVersion,consented:true,scenario:'verified'});return {port:await sandboxIdentityProvider(runtime),input:{applicantId:caseId,applicantVersion:2,captureReference:capture.captureReference,consentVersion:capture.consentVersion}};}});return {...x,runtime,close(){x.db.sql.close();runtime.DB.sql.close();}};}
